args.query:
MATCH (ont:Device {device_type:'ont'})-[:DELIVERS]->(s:Service)<-[:SUBSCRIBES_TO]-(c:Customer)
WHERE ont.op_state = 'failed' OR EXISTS {
  MATCH (ont)-[:UPLINKS_TO*1..]->(up:Device)
  WHERE up.op_state = 'failed'
}
RETURN count(DISTINCT c) AS cnt

