args.query:
MATCH (c:Customer)-[:SUBSCRIBES_TO]->(s:Service)
WHERE NOT EXISTS {
  MATCH (ont:Device {device_type: 'ont'})-[:DELIVERS]->(s)
  WHERE ont.status = 'active'
    AND NOT EXISTS {
      MATCH path = (ont)-[:FEEDS*0..]->(d:Device)
      WHERE d.status = 'failed'
    }
}
RETURN count(c) AS customers_without_service

